/// One item of a collection, by its place in the list.
class SettingItemData {
  SettingItemData({
    required this.title,
    this.byline,
    this.subtitle,
    this.error,
    this.icon,
    this.tone = SettingTone.plain,
    this.on,
    this.actions = const [],
    this.image,
    this.opens,
    this.bot,
    this.botColour,
    this.botLive = true,
    this.tap,
    this.badge,
    this.editable = true,
    this.meters = const [],
  });

  String title;

  /// What it has spent, a line each under its words.
  List<SettingMeterData?> meters;

  /// Who made it, or how much it holds, under its title.
  String? byline;
  String? subtitle;
  String? error;
  SettingIcon? icon;
  SettingTone tone;

  /// Its picture, as a PNG: an agent's face.
  Uint8List? image;

  /// Its face as a Bot Avatar, drawn live: its key, for
  /// [SettingsIntents.botGeometry] and [SettingsIntents.botFrame], and its
  /// colour as 0xRRGGBB.
  String? bot;
  int? botColour;

  /// False draws [bot] still.
  bool botLive;

  /// A page of the app's that tells more of it.
  TextPageData? opens;

  /// Whether it is armed, where its row carries a switch.
  bool? on;

  /// The item action a tap on the row runs.
  String? tap;

  /// Where an entry not of this level came from: "Bundled", "Inherited".
  String? badge;

  /// Whether it is edited through the list's form.
  bool editable;

  List<SettingItemActionData?> actions;
}

