/// A pairing in flight.
/// What is done to one thing of a catalog, or to the catalog itself.
enum CatalogOp { download, cancel, delete, add }

/// A step of pairing the client took.
enum PairingOp { openWindow, closeWindow, match, mismatch, scan, cancel }

enum SetupOp { setUp, importTool, delete }

/// Where a pairing stands: the core's `PairingStage`, name for name.
enum SettingPairingStage { connecting, confirming, done, failed }

class SettingPairingData {
  SettingPairingData({
    required this.stage,
    this.qr,
    this.code,
    this.sas,
    this.peerName,
    this.error,
  });

  SettingPairingStage stage;
  String? qr;
  String? code;
  String? sas;
  String? peerName;
  String? error;
}

class SettingToolData {
  SettingToolData({required this.name, this.version});

  String name;
  String? version;
}

/// Everything a row may say, its [kind] saying which of it is meaningful.
class SettingRowData {
  SettingRowData({
    required this.id,
    required this.kind,
    required this.hint,
    required this.title,
    this.detail,
    this.footnote,
    this.enabled = true,
    this.icon,
    this.parent,
    this.accessory = false,
    this.on,
    this.effective = false,
    this.unsettable = false,
    this.options = const [],
    this.picked,
    this.inheritedLabel,
    this.noneLabel,
    this.error,
    this.groups = const [],
    this.slotPicks = const [],
    this.value,
    this.inherited,
    this.stops = const [],
    this.min,
    this.max,
    this.unit,
    this.entries = const {},
    this.masked = true,
    this.label,
    this.destructive = false,
    this.secondary = false,
    this.busy = false,
    this.modelLabel,
    this.text,
    this.emptyLabel,
    this.prompt,
    this.secret = false,
    this.lines = 1,
    this.submitLabel,
    this.clearLabel,
    this.notice = const [],
    this.tone = SettingTone.plain,
    this.items = const [],
    this.addLabel,
    this.removeLabel,
    this.removable = true,
    this.editable = false,
    this.emptyItems,
    this.catalog = const [],
    this.info = const [],
    this.page,
    this.summary,
    this.pairing,
    this.canScan = false,
    this.blocked,
    this.setupNotice,
    this.prerequisiteWhy,
    this.prerequisiteCommand,
    this.tools,
    this.running = false,
    this.deleteConfirm,
    this.setUpLabel,
    this.importLabel,
    this.deleteLabel,
    this.markdown = false,
    this.editing = false,
    this.webUrl,
    this.inheritedPick,
    this.iconOnly = false,
    this.adds,
    this.fileName,
  });

  String id;
  SettingKind kind;
  SettingHint hint;
  String title;
  String? detail;
  String? footnote;
  bool enabled;
  SettingIcon? icon;

  /// The row this one belongs to: a group's own, or the row it is drawn at
  /// the end of where [accessory]. Such a row comes after its parent in the
  /// section's list and is drawn as part of it, not on its own.
  String? parent;
  bool accessory;

  // toggle
  bool? on;
  bool effective;
  bool unsettable;

  // choice, slots
  List<SettingOptionData?> options;

  /// The option picked, by its place; null for none, or unset.
  int? picked;
  String? inheritedLabel;
  String? noneLabel;
  String? error;
  List<SettingGroupData?> groups;

  /// Each slot's pick, by its place among every group's options in order.
  List<int?> slotPicks;

  // range, number
  int? value;
  int? inherited;
  List<int?> stops;
  int? min;
  int? max;
  String? unit;

  // keyValues
  Map<String?, String?> entries;
  bool masked;

  // action
  String? label;
  bool destructive;
  bool secondary;

  // group: its rows are the ones naming it their parent
  bool busy;

  // modelPick
  String? modelLabel;

  // text
  String? text;
  String? emptyLabel;
  String? prompt;
  bool secret;
  int lines;
  String? submitLabel;
  String? clearLabel;

  // notice
  List<SettingLineData?> notice;
  SettingTone tone;

  // collection
  List<SettingItemData?> items;
  String? addLabel;
  String? removeLabel;
  bool removable;

  /// Whether items are added and edited through a form.
  bool editable;

  String? emptyItems;

  // catalog
  List<SettingCatalogData?> catalog;

  // info
  List<SettingInfoData?> info;

  // subpage
  SettingsPageKey? page;
  String? summary;

  // pairing
  SettingPairingData? pairing;
  bool canScan;

  // setup
  String? blocked;
  String? setupNotice;
  String? prerequisiteWhy;
  String? prerequisiteCommand;
  List<SettingToolData?>? tools;
  bool running;
  SettingConfirmData? deleteConfirm;

  /// A setup row's three buttons.
  String? setUpLabel;
  String? importLabel;
  String? deleteLabel;

  // document: its text is [text], each edit said back by setText
  bool markdown;
  bool editing;

  // web
  String? webUrl;

  // choice: the option unset stands for, by its place
  int? inheritedPick;

  /// An action's button is its icon alone, its label the tooltip.
  bool iconOnly;

  /// An action opening the new-item form of the collection with this id.
  String? adds;

  /// A document's file name, which picks its grammar.
  String? fileName;
}

class SettingsSectionData {
