  String id;
  String title;
  String? detail;

  /// Said under the rows: how what they show was counted.
  String? footnote;
  List<SettingRowData?> rows;

  /// Its one row is the whole of its page: a file, a web page.
  bool fills;
}

class SettingsPageData {
  SettingsPageData({
    required this.key,
    required this.title,
    this.groupStart = false,
    this.openedFrom,
    this.sections = const [],
    this.address,
    this.subtitle,
    this.toolbar = const [],
    this.guarded = false,
    this.held = false,
  });

  SettingsPageKey key;
  String title;
  bool groupStart;

  /// The page whose row opens this one; none for a page offered among the
  /// others.
  SettingsPageKey? openedFrom;
  List<SettingsSectionData?> sections;

  /// An app page's: which it is.
  String? address;
  String? subtitle;

  /// The bar's actions, the first the page's own.
  List<SettingRowData?> toolbar;

  /// Whether leaving asks first ([SettingsIntents.leavePage]), so it is not
  /// swiped away.
  bool guarded;

  /// Whether it is left only by its own actions: drawn as a card nothing
  /// dismisses.
  bool held;
}

/// Every page this platform offers, as it stands.
class SettingsSnapshot {
  SettingsSnapshot({required this.pages});

  List<SettingsPageData?> pages;
}

/// What an action asks before it runs.
class SettingConfirmData {
  SettingConfirmData({
    required this.title,
    required this.message,
    this.confirmLabel,
    this.destructive = false,
    this.brief = false,
    this.cancelled = false,
  });

  String title;
  String message;

  /// Null: nothing to confirm, only something to say; the action stops.
  String? confirmLabel;
  bool destructive;

  /// Said in passing, and the action stops.
  bool brief;

  /// Nothing to say, and the action stops.
  bool cancelled;
}

class SettingNoticeData {
  SettingNoticeData({required this.message, this.title, this.copy});

  String? title;
  String message;

  /// Text put on the clipboard as the notice is said.
  String? copy;
}

enum FormPartKind {
  question,
  text,
  choice,
  date,
  duration,
  multi,
  note,
  prompt,
  link,
  fold,
  consent,
  entries,
  signIn,
}

class FormPartData {
  FormPartData({
    required this.kind,
    this.id,
    this.label,
    this.hint,
    this.helper,
    this.error,
    this.focused = false,
    this.lines = 1,
    this.options = const [],
    this.enabled = true,
    this.segmented = false,
    this.cards = false,
    this.secret = false,
    this.file = false,
    this.url,
    this.prominent = false,
    this.message,
    this.accept,
    this.linkLabel,
    this.all = false,
    this.on = false,
    this.flipped,
  });

  FormPartKind kind;
  String? id;

  /// A question's text, or a field's label.
  String? label;
  String? hint;
  String? helper;
  String? error;
  bool focused;
  int lines;

  /// A choice's options, each the answer it stores and its label and help.
  List<FormOptionData?> options;

  bool enabled;

  /// A choice drawn with every option side by side.
  bool segmented;

  /// A choice drawn as a card per option, under its group, with its help
  /// and tags.
  bool cards;

  /// Text typed hidden.
  bool secret;

  /// Text a file picked from the disk fills, its path the answer.
  bool file;

  /// A link's, and a consent's terms.
  String? url;
  bool prominent;

  /// A consent's: what is agreed to, what agreeing is called, and what its
  /// terms' link says. Its title is [label].
  String? message;
  String? accept;
  String? linkLabel;

  /// A multi's label is a switch over all its options: on while each kind
  /// has one picked, and switched on, each kind's first.
  bool all;

  /// A fold open, a consent given, a multi's [all] switch on; and what a
  /// tap on it answers.
  bool on;
  String? flipped;
}

class FormTagData {
  FormTagData({required this.text, this.tone = SettingTone.plain});

  String text;
  SettingTone tone;
}

class FormOptionData {
  FormOptionData({
    required this.answer,
    required this.label,
