/// A paired device's connection, as the sync hub's `PeerStatus`.
enum DeviceStatus { connecting, online, offline, error }

/// What a paired device's page can have done to it.
enum DeviceOp { connect, disconnect, rename, revoke }

/// A paired device as this device holds it: the record, its connection, and
/// the two fingerprints a pair exists to compare.
class PairedDeviceData {
  PairedDeviceData({
    required this.id,
    required this.name,
    required this.status,
    this.error,
    required this.lastSeenMs,
    required this.addedMs,
    this.addresses = const [],
    this.fingerprint,
    required this.ownFingerprint,
  });

  String id;
  String name;
  DeviceStatus status;
  String? error;

  /// Milliseconds since the epoch.
  int lastSeenMs;
  int addedMs;

  /// Where its LAN server was last heard, host:port each.
  List<String> addresses;

  /// Over the key this device stored at the pair; none where it will not
  /// decode.
  String? fingerprint;

  /// This device's own.
  String ownFingerprint;
}

/// What the app says to the client.
@HostApi(dartHostTestHandler: "TestNativeSettings")
abstract class NativeSettings {
  /// Every page, replacing what the client held.
  void settings(SettingsSnapshot snapshot);

  /// Show the settings, at [page] where it names one.
  void show(SettingsPageKey? page);

  /// Open paired device [id]'s page over the one shown.
  void openDevice(String id);

  /// Device [id] as it now stands, while its page is shown; none once it is
  /// no longer paired, or with [readError] where the record could not be
  /// read.
  void device(String id, PairedDeviceData? device, String? readError);

  /// The app's pages open over the window, the first at the bottom; none
  /// takes them all down.
  void appPages(List<SettingsPageData> stack);

  /// The open form's program account as it now stands, while its sign-in
  /// row is shown.
  void cliAccount(CliAccountData account);
}

/// Where a CLI program's account stands: the core's `CliAccountStage`, name
/// for name.
enum CliAccountStep {
  checking,
  signedIn,
  signedOut,
  installing,
  starting,
  waiting,
  failed,
}

class CliAccountData {
  CliAccountData({
    required this.step,
    required this.plan,
    required this.program,
    required this.signingIn,
    this.progress,
    this.page,
    this.failure,
  });

  CliAccountStep step;

  /// What the account is called: "Claude", "ChatGPT".
  String plan;

  /// The program's name, for the row and the install.
  String program;

  /// Whether a sign-in is under way or has failed, which the sheet shows.
  bool signingIn;

  /// An install's, 0 to 1; none while it cannot say.
  double? progress;

  /// The page to sign in on, while waiting.
  String? page;
  String? failure;
}

enum CliAccountOp { signIn, signInAgain, cancel }

/// What the client says the user did, by row id. A row inside a group is
/// named by its own id. The answers that wait return what the client shows
/// next: a confirm, a notice, a form.
@FlutterApi()
abstract class SettingsIntents {
  /// Whether the settings are on screen, and which of their pages are drawn:
  /// the one picked and those pushed over it. Every page is sent while they
  /// are up, but only [pages] with their rows — a page reads what only it
  /// shows (each provider's usage, the skills on disk, the browsers
  /// installed, a model's download), which a page nobody is looking at
  /// should not pay for, nor resend on every tick.
  void shown(bool on, List<SettingsPageKey> pages);

  void toggle(String id, bool? on);

  /// Picks [option] by its place, or nothing.
  void pick(String id, int? option);

  void pickSlot(String id, int slot, int option);

  void setNumber(String id, int? value);

  void setText(String id, String text);

  /// A web row landed on [url], a page called [title].
  void navigated(String id, String url, String? title);

  void putEntry(String id, String name, String value, String? replacing);

  void removeEntry(String id, String name);

  void setModel(String id, String? providerId, String? modelId);

  /// What [id]'s action asks before it runs, or null to run it now.
  @async
  SettingConfirmData? ask(String id);

  /// Runs [id]'s action, once what it asked was agreed to.
  @async
  SettingNoticeData? run(String id);

  @async
  SettingNoticeData? itemAction(String id, int index, String action);

  void removeItem(String id, int index);

  /// Sets the item at [index]'s picture to [png].
  void itemImage(String id, int index, Uint8List png);

  /// The item at [index] wearing the Bot Avatar [key] — the stage's — in
  /// [colour], 0xRRGGBB.
  void itemBotAvatar(String id, int index, String key, int colour);

  /// The form for the item at [index], or a new one, as [answers] stand;
  /// null answers are its first.
  @async
  SettingFormData form(String id, int? index, Map<String?, String?>? answers);

  @async
  FormSaveData? submitForm(
    String id,
    int? index,
    Map<String?, String?> answers,
  );

  /// Watches the account of the program the form's sign-in names, as
  /// [answers] stand, sent by `cliAccount` until [closeCliAccount].
  void openCliAccount(String id, int? index, Map<String?, String?> answers);

  void cliAccountOp(CliAccountOp op);

  /// A code the sign-in page showed, pasted back.
  void cliAccountCode(String code);

  void closeCliAccount();

  /// The form left unsaved, as [answers] stood.
  void formDismissed(String id, int? index, Map<String?, String?> answers);

  /// [item] is "" for [CatalogOp.add].
  void catalog(String id, String item, CatalogOp op);

  void pairing(String id, PairingOp op);

  /// Which paired device's page is on screen, none once it goes: the device
  /// is sent while one is.
  void deviceShown(String? id);

  /// [op] on paired device [id], [name] its new one for a rename; what went
  /// wrong, where something did.
  @async
  SettingNoticeData? deviceAction(String id, DeviceOp op, String? name);

  /// Pairs with [code], a code or an invite's answer.
  @async
  String? pairWith(String id, String code);

  @async
  String createInvite(String id);

  void setup(String id, SetupOp op);

  /// A model picker's quick picks and every model the role can use.
  @async
  ModelPickerData models(String id);

  /// Stars or unstars a model, for every picker.
  void toggleFavourite(String providerId, String modelId);

  /// The form adding a model to the picker [id] — on [providerId] where the
  /// picker is narrowed to one — or editing [modelId] on it, as [answers]
  /// stand; null answers are its first.
  @async
  SettingFormData modelForm(
    String id,
    String? providerId,
    String? modelId,
    Map<String?, String?>? answers,
  );

  @async
  FormSaveData? submitModelForm(
    String id,
    String? providerId,
    String? modelId,
    Map<String?, String?> answers,
  );

  /// Deletes a model added by hand.
  void deleteModel(String providerId, String modelId);

  /// A Bot Avatar's slices, sent once: what its frames name by place
  /// (`BotStage.geometry`). Null for a key never handed out.
  @async
  Float64List? botGeometry(String key);

  /// One frame of the avatar [instance], wearing [key], [nowMs] into its own
  /// clock (`encodeFrame`): live, or a still, or the thumbnail's pose.
  /// [mood] is idle, thinking or happy by place; [turnYaw] and [turnPitch]
  /// a drag's turn. [pointerX] and [pointerY] are where the pointer is over
  /// the avatar's [size]-square box, from its top left, null where there is
  /// none to follow. The core animates; the client draws what it is sent.
  @async
  Float64List? botFrame(
    String instance,
    String key,
    int mood,
    bool live,
    bool thumbnail,
    double nowMs,
    double turnYaw,
    double turnPitch,
    double? pointerX,
    double? pointerY,
    double size,
  );

  /// A tap on [instance] [nowMs] into its clock: it reacts, and is live
  /// while the reaction plays, which [botFrame]'s next answers say.
  void botTap(String instance, double nowMs);

  /// [instance] has left the screen.
  void botDrop(String instance);

  /// The avatars the editor offers, opened for [agent] or to browse.
  @async
  BotAvatarsData botAvatars(String? agent);

  /// Imports the definitions in [text].
  @async
  BotImportData importBotAvatars(String text);

  /// Deletes an import of the user's, answering once it is gone.
  @async
  void deleteBotAvatar(String key);

  /// What leaving app page [address] asks first, or null once it has gone.
  @async
  SettingConfirmData? leavePage(String address);

  /// App page [address] gone, whatever it would have asked: the user agreed,
  /// or it was taken down.
  void closePage(String address);

  /// The text of a page the app holds: the privacy policy, the licences.
  @async
  String page(TextPageData opens);
}
